// path: scripts/changelog.mjs
/**
 * npm run changelog -- rewrite CHANGELOG.md from the commit history.
 *
 * The changelog is generated, never written. Every entry is a commit of this
 * repository, read with `git log` and grouped by the type the commit
 * convention already requires (`docs/PLAN/07_BRANCH_AND_GIT_WORKFLOW.md`
 * section 3), so an entry that is not in the history cannot appear in the file
 * and a change that was committed cannot be forgotten. This is what
 * FEATURE_LIST item 3519 asks for, and it is why the file carries a
 * "generated by" line instead of a list of dates someone maintains by hand.
 *
 * Grouping, which is the only judgement the script makes:
 *
 *   - feat                -> Added
 *   - refactor, perf,     -> Changed
 *     chore, style, build
 *   - fix                 -> Fixed
 *   - security            -> Security
 *   - docs                -> Documentation
 *   - anything else       -> Other
 *
 * A subject that does not parse as a conventional commit is grouped under
 * Other rather than dropped, because a generator that silently loses a commit
 * is worse than one that shows an untidy line.
 *
 * The output is deliberately stable: sections are emitted in the order above
 * and only when they have entries, and entries keep the order `git log`
 * returns them in, newest first. Two runs over the same history produce the
 * same bytes, so a regeneration produces a reviewable diff.
 */
import { execFileSync } from 'node:child_process';
import { writeFileSync } from 'node:fs';
import { join } from 'node:path';

const OUTPUT_FILE = 'CHANGELOG.md';
const COMMIT_FORMAT = '%h%x09%s';
const SUBJECT_PATTERN = /^([a-z]+)(?:\(([^)]*)\))?!?:\s+(.+)$/;

const SECTIONS = [
  { id: 'Added', types: ['feat'] },
  { id: 'Changed', types: ['refactor', 'perf', 'chore', 'style', 'build'] },
  { id: 'Fixed', types: ['fix'] },
  { id: 'Security', types: ['security'] },
  { id: 'Documentation', types: ['docs'] },
  { id: 'Other', types: [] },
];

const HEADER = [
  '// path: CHANGELOG.md',
  '# Changelog',
  '',
  'Every change to KD SOLUTION IT is recorded in this file. The entries are',
  'generated from the commit history by `npm run changelog` and the file is',
  'never edited by hand: a change that is not in the history is not in this',
  'file, and a change that is committed appears here at the next handoff.',
  '',
  'The format follows Keep a Changelog. Changes are grouped by the commit type',
  'that introduced them and the newest entry is first within a section.',
  '',
  '## Unreleased',
  '',
];

/** Every commit of the current branch, newest first: { sha, subject }. */
function readCommits() {
  const output = execFileSync('git', ['log', '--no-merges', `--pretty=format:${COMMIT_FORMAT}`], {
    encoding: 'utf8',
    maxBuffer: 32 * 1024 * 1024,
  });
  return output
    .split('\n')
    .map((line) => line.trimEnd())
    .filter((line) => line.length > 0)
    .map((line) => {
      const separator = line.indexOf('\t');
      return { sha: line.slice(0, separator), subject: line.slice(separator + 1) };
    });
}

/** The section a commit belongs to, and the text of its entry. */
function classify(commit) {
  const match = SUBJECT_PATTERN.exec(commit.subject);
  if (match === null) {
    return { section: 'Other', scope: null, summary: commit.subject };
  }
  const [, type, scope, summary] = match;
  const section = SECTIONS.find((entry) => entry.types.includes(type));
  return { section: section === undefined ? 'Other' : section.id, scope: scope ?? null, summary };
}

function renderEntry(commit) {
  const { scope, summary } = classify(commit);
  const origin = scope === null ? commit.sha : `${scope}, ${commit.sha}`;
  return `- ${summary} (${origin})`;
}

function render(commits) {
  const bySection = new Map(SECTIONS.map((section) => [section.id, []]));
  for (const commit of commits) {
    bySection.get(classify(commit).section).push(renderEntry(commit));
  }
  const lines = [...HEADER];
  let entryCount = 0;
  for (const section of SECTIONS) {
    const entries = bySection.get(section.id);
    if (entries.length === 0) {
      continue;
    }
    lines.push(`### ${section.id}`, '');
    for (const entry of entries) {
      lines.push(entry);
      entryCount += 1;
    }
    lines.push('');
  }
  return { text: `${lines.join('\n').trimEnd()}\n`, entryCount };
}

function main() {
  const commits = readCommits();
  const { text, entryCount } = render(commits);
  writeFileSync(join(process.cwd(), OUTPUT_FILE), text, 'utf8');
  const grouped = SECTIONS.filter((section) =>
    commits.some((commit) => classify(commit).section === section.id),
  ).map((section) => section.id);
  process.stdout.write(
    `changelog: ${String(entryCount)} entries from ${String(commits.length)} commits, ` +
      `sections ${grouped.join(', ')}\n`,
  );
}

main();
